import time
from collections import OrderedDict
from typing import Any, Optional

class LruCacheTTL:
    def __init__(self, capacity: int, default_ttl: float = 60.0):
        assert capacity > 0, 'Capacity must be positive'
        self.capacity = capacity
        self.default_ttl = default_ttl
        self.cache: OrderedDict[Any, tuple[Any, float]] = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self.cache:
            return None
        val, expires_at = self.cache[key]
        if time.time() > expires_at:
            del self.cache[key]
            return None
        self.cache.move_to_end(key)
        return val

    def set(self, key: Any, val: Any, ttl: Optional[float] = None) -> None:
        ttl_val = self.default_ttl if ttl is None else ttl
        expires_at = time.time() + ttl_val
        if key in self.cache:
            self.cache.move_to_end(key)
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
        self.cache[key] = (val, expires_at)

    def cleanup_expired(self) -> int:
        now = time.time()
        expired = [k for k, (_, exp) in self.cache.items() if now > exp]
        for k in expired:
            del self.cache[k]
        return len(expired)

    def __len__(self) -> int:
        return len(self.cache)
